import "../App.css";

function HistoryModal({ history, onClose }) {
  if (!history) return null;

  return (
    <div className="modal-overlay">
      <div className="history-modal">
        <button
          className="close-btn"
          onClick={onClose}
        >
          ✕
        </button>

        <h2>{history.tool_name.toUpperCase()}</h2>

        <p className="history-date">
          {new Date(history.created_at).toLocaleString()}
        </p>

        {/* ================= INPUT ================= */}

        <div className="modal-section">
          <h3>Input</h3>

          {history.tool_name === "proposal" && (
            <>
              <p>
                <strong>Platform:</strong>{" "}
                {history.input_data?.platform}
              </p>

              <p>
                <strong>Skill:</strong>{" "}
                {history.input_data?.skill}
              </p>

              <p>
                <strong>Tone:</strong>{" "}
                {history.input_data?.tone}
              </p>

              <p>
                <strong>Length:</strong>{" "}
                {history.input_data?.length}
              </p>

              <p>
                <strong>Job Post</strong>
              </p>

              <textarea
                readOnly
                value={history.input_data?.job_post || ""}
              />
            </>
          )}

          {history.tool_name === "seo" && (
            <>
              <p>
                <strong>Title:</strong>{" "}
                {history.input_data?.title}
              </p>

              <p>
                <strong>Category:</strong>{" "}
                {history.input_data?.category}
              </p>

              <p>
                <strong>Description</strong>
              </p>

              <textarea
                readOnly
                value={history.input_data?.description || ""}
              />
            </>
          )}

          {history.tool_name === "profile" && (
            <>
              <p>
                <strong>Profile</strong>
              </p>

              <textarea
                readOnly
                value={history.input_data?.profile || ""}
              />
            </>
          )}
        </div>

        {/* ================= OUTPUT ================= */}

        <div className="modal-section">
          <h3>Output</h3>

          {/* ---------- Proposal ---------- */}

          {history.tool_name === "proposal" && (
            <>
              <p>
                <strong>Proposal</strong>
              </p>

              <textarea
                readOnly
                value={history.output_data?.proposal || ""}
              />

              {history.output_data?.key_points?.length > 0 && (
                <>
                  <h4>Key Points</h4>

                  <ul className="history-list">
                    {history.output_data.key_points.map(
                      (point, index) => (
                        <li key={index}>{point}</li>
                      )
                    )}
                  </ul>
                </>
              )}

              <p>
                <strong>Word Count:</strong>{" "}
                {history.output_data?.word_count}
              </p>
            </>
          )}

          {/* ---------- SEO ---------- */}

          {history.tool_name === "seo" && (
            <>
              <p>
                <strong>Optimized Title</strong>
              </p>

              <textarea
                readOnly
                value={
                  history.output_data?.title ||
                  history.output_data?.optimized_title ||
                  ""
                }
              />

              <p>
                <strong>Category</strong>
              </p>

              <input
                readOnly
                value={
                  history.output_data?.category ||
                  ""
                }
              />

              <p>
                <strong>Description</strong>
              </p>

              <textarea
                readOnly
                value={
                  history.output_data?.description ||
                  history.output_data?.optimized_description ||
                  ""
                }
              />
            </>
          )}

          {/* ---------- Profile ---------- */}

          {history.tool_name === "profile" && (
            <>
              <p>
                <strong>Score:</strong>{" "}
                {history.output_data?.score}
              </p>

              <h4>Strengths</h4>

              <ul className="history-list">
                {(history.output_data?.strengths || []).map(
                  (item, index) => (
                    <li key={index}>{item}</li>
                  )
                )}
              </ul>

              <h4>Weaknesses</h4>

              <ul className="history-list">
                {(history.output_data?.weaknesses || []).map(
                  (item, index) => (
                    <li key={index}>{item}</li>
                  )
                )}
              </ul>

              <h4>Suggestions</h4>

              <ul className="history-list">
                {(history.output_data?.suggestions || []).map(
                  (item, index) => (
                    <li key={index}>{item}</li>
                  )
                )}
              </ul>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

export default HistoryModal;
